<?php
namespace App\Http\Controllers;
use App\Http\Requests\ProductRequest; use App\Models\Product; use Illuminate\Http\Request;
class ProductController extends Controller { public function index(Request $r){return response()->json(['data'=>Product::with('category')->where('restaurant_id',$r->user()->restaurant_id)->orderBy('name')->get()]);} public function store(ProductRequest $r){$p=Product::create(['restaurant_id'=>$r->user()->restaurant_id,...$r->validated()]);return response()->json(['data'=>$p->load('category')],201);} public function show(Request $r,int $id){return response()->json(['data'=>Product::with('category')->where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id)]);} public function update(ProductRequest $r,int $id){$p=Product::where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id);$p->update($r->validated());return response()->json(['data'=>$p->load('category')]);} public function destroy(Request $r,int $id){Product::where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id)->delete();return response()->json(['message'=>'تم حذف المنتج بنجاح']);} }
